(function(root){
function output(data){
 if(data?.error)throw Error('服务商错误：'+(data.error.message||String(data.error)));
 const c=data?.choices?.[0],m=c?.message||c?.delta||{},parts=x=>typeof x==='string'?x:Array.isArray(x)?x.map(v=>typeof v==='string'?v:v?.text?.value||v?.text||v?.content||'').filter(x=>typeof x==='string').join(''):'';
 const text=parts(m.content)||parts(data?.output_text)||parts(data?.content)||(Array.isArray(data?.output)?data.output:[]).map(v=>v.type==='message'?parts(v.content):'').join('');
 if(text.trim())return text;
 if(c?.finish_reason==='content_filter'||m.refusal)throw Error('服务商过滤或拒绝了这次回复，没有返回正文');
 if(c?.finish_reason==='length'||m.reasoning_content||m.reasoning)throw Error('模型只返回了思考内容或耗尽输出额度，没有生成正式回复；可提高输出额度或更换聊天模型');
 throw Error('接口返回成功，但没有可显示的正文；测试连接成功不代表长上下文或群聊请求一定成功')
}
function bubbles(text,name,actions=false,max=10){const n=String(name||'').replace(/[.*+?^${}()|[\]\\]/g,'\\$&');text=String(text).replace(/\[\[气泡\]\]/g,'\n\n');if(n)text=text.replace(new RegExp('^\\s*(?:\\['+n+'\\]|【'+n+'】|'+n+'[：:])\\s*[：:]?\\s*','gm'),'');if(!actions)text=text.replace(/[（(][^()（）\n]{0,300}[）)]/g,'');let a=text.split(/\n{2,}/).map(s=>s.trim()).filter(Boolean);max=Math.min(10,Math.max(1,Number(max)||10));if(a.length>max)a=[...a.slice(0,max-1),a.slice(max-1).join('\n')];return a}
function rotate(list,n){return list.length?[...list.slice(n%list.length),...list.slice(0,n%list.length)]:[]}
function settle(w,m,accept,L,at){const n=L.normalize(w),c=m.card,id='settle:'+m.id;if(!c||c.type!=='transfer'||!['pending','sent'].includes(c.status))return {wallet:w,changed:false};if(n.ledger.some(x=>x.id===id)||n.roleTransfers.some(x=>x.settlementId===id))return {wallet:w,changed:false};if(!/^\d+(?:\.\d{1,2})?$/.test(String(c.amount)))throw Error('金额无效');const amount=String(c.amount),cents=Number(BigInt(amount.split('.')[0])*100n+BigInt((amount.split('.')[1]||'').padEnd(2,'0')));if(!Number.isSafeInteger(cents)||cents<1)throw Error('金额无效');const peer=m.role==='user'?c.recipient:m.sender;if(!peer)throw Error('找不到交易对方');let row=n.roleTransfers.find(x=>x.id===m.id);if(row&&(row.cents!==cents||row.sender!==peer))throw Error('交易金额或交易对方不一致');if(!row){row={id:m.id,cents,sender:peer,status:m.role==='user'?'sent':'unreserved'};n.roleTransfers.push(row)}const account=JSON.parse(JSON.stringify(L.account(n,peer))),changeRole=delta=>{if(!Number.isSafeInteger(account.balance+delta)||account.balance+delta<0)throw Error('角色余额不足，无法处理这笔转账');account.balance+=delta;account.ledger.push({id,at,type:'transfer-'+(accept?'received':'returned'),delta,balance:account.balance});n.accounts[peer]=account};let delta=0;
if(m.role==='user'){if(accept){if(row.status==='reserved-user')changeRole(cents)}else{if(row.status!=='reserved-user')changeRole(-cents);delta=cents}}else{if(accept){if(row.status==='unreserved')changeRole(-cents);delta=cents}else if(row.status==='reserved')changeRole(cents)}if(!Number.isSafeInteger(n.balance+delta))throw Error('零钱金额超出范围');n.balance+=delta;n.ledger.push({id,messageId:m.id,type:'transfer-'+(accept?'received':'returned'),delta,balance:n.balance,note:accept?'确认收款':'转账退回',createdAt:at});row.status=accept?'received':'returned';row.settlementId=id;return {wallet:n,changed:true,status:row.status,peer}}
const api={output,bubbles,rotate,settle};root.Chat26=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window==='undefined'?globalThis:window);
